from pathlib import Path
import re
import sys

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else '.')


def read(rel):
    return (ROOT/rel).read_text(encoding='utf-8')

def write(rel, text):
    (ROOT/rel).write_text(text, encoding='utf-8', newline='\n')

def rep(text, old, new, label, count=1):
    n = text.count(old)
    if n != count:
        raise RuntimeError(f'{label}: expected {count} occurrences, found {n}')
    return text.replace(old, new, count)

def insert_before(text, marker, payload, label):
    if marker not in text:
        raise RuntimeError(f'{label}: marker not found')
    return text.replace(marker, payload + marker, 1)

def extract_balanced_function(text, start_marker):
    start = text.find(start_marker)
    if start < 0:
        raise RuntimeError(f'function marker not found: {start_marker}')
    brace = text.find('{', start)
    if brace < 0:
        raise RuntimeError('opening brace not found')
    depth = 0
    i = brace
    in_str = False
    esc = False
    while i < len(text):
        ch = text[i]
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
        else:
            if ch == '"':
                in_str = True
            elif ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    return start, i + 1, text[start:i+1]
        i += 1
    raise RuntimeError('unterminated function')

