hlsl = rep(hlsl, '''                    previous_sample = sample_previous_target(\n                        pixel + residual_backward * 0.5, Slice, ViewIndex);\n                    current_sample = sample_current_target(\n                        pixel - residual_backward * 0.5, Slice, ViewIndex);''', '''                    const float alpha = interpolation_alpha();\n                    previous_sample = sample_previous_target(\n                        pixel + residual_backward * alpha, Slice, ViewIndex);\n                    current_sample = sample_current_target(\n                        pixel - residual_backward * (1.0 - alpha), Slice, ViewIndex);''', 'flow warp alpha')
